#!/usr/bin/env bash
set -euo pipefail
ROOT="${1:-${PROJECT_ROOT:-.}}"
APP="$ROOT/memeflow-app"
[[ -f "$APP/index.html" ]] || APP="$ROOT"
INDEX="$APP/index.html"
[[ -f "$INDEX" ]] || { echo "ERROR: index.html not found."; exit 1; }
DIR="$APP/.memeflow-patches/plans-billing-clean-v3"
mkdir -p "$DIR"
STAMP="$(date +%Y%m%d-%H%M%S)"
BACKUP="$DIR/index.html.$STAMP.bak"
WORK="$DIR/index.html.$STAMP.work"
PYTMP="$DIR/install.$STAMP.py"
cp "$INDEX" "$BACKUP"
cp "$INDEX" "$WORK"
rollback(){
  cp "$BACKUP" "$INDEX" 2>/dev/null || true
  rm -f "$WORK" "$PYTMP"
}
trap 'echo "ERROR: Billing V3 failed; restoring exact pre-install index.html."; rollback' ERR
printf '%s' '' | base64 -d > "$PYTMP"
python3 "$PYTMP" "$WORK"
cp "$WORK" "$INDEX"
rm -f "$WORK" "$PYTMP"
cat > "$DIR/latest-manifest.txt" <<EOF
INDEX=$INDEX
BACKUP=$BACKUP
EOF
trap - ERR
echo
echo "OK: PLANS & BILLING CLEAN V3 installed."
echo "V2 owner replaced, not overlaid."
echo "Stop -> Run, then hard-refresh Safari."
